'use strict';
const fs=require('fs'),path=require('path');
const suiteI18n=require('./i18n');
const {DirectoryStore,profileLogTag,filename}=require('./logging-core');
class AutoLoggerSettingsTabComponent {
  constructor(config,electron,hostWindow,cd,zone,elementRef) {Object.assign(this,{config,electron:electron||{},hostWindow,cd,zone,elementRef});this.profileEntries=[];this.profileGroups=[];this.logSearch='';this.logSort='newest';this.directoryStore=new DirectoryStore(config);}
  t(text) {return suiteI18n.t(text,this.config);}
  getConfig() {return this.config.store.autoSessionLogger;}
  profileName(entry) {return suiteI18n.profileName((this.config.store.profiles||[]).find(p=>String(p.id)===String(entry.id))||entry,this.config);}
  ngOnInit() {this.languageChanged=()=>this.render();if(typeof window!=='undefined')window.addEventListener('tabby-session-suite-language-changed',this.languageChanged);}
  ngAfterViewInit() {this.mount=this.elementRef?.nativeElement?.querySelector?.('[data-log-settings-mount]')||this.elementRef?.nativeElement;this.refreshProfiles();}
  ngOnDestroy() {if(typeof window!=='undefined')window.removeEventListener('tabby-session-suite-language-changed',this.languageChanged);}
  refreshProfiles() {
    const profiles=(this.config.store.profiles||[]).filter(p=>p.type==='ssh'&&!p.isTemplate),groups=this.config.store.groups||[],nodes=new Map();this.profileEntries=profiles.map(p=>{const o=p.options||{};return {id:String(p.id),name:p.name,host:o.host||'',port:o.port||22,user:o.user||o.username||'',profile:p,directory:this.directoryStore.specific(p),logs:[],logsExpanded:false};});
    const root={key:'__ungrouped__',id:'__ungrouped__',name:this.t('Ungrouped'),entries:[],children:[],totalProfiles:0};for(const g of groups)nodes.set(String(g.id),{key:String(g.id),id:String(g.id),name:g.name,entries:[],children:[],totalProfiles:0});
    for(const g of groups){const n=nodes.get(String(g.id)),parent=nodes.get(String(g.parentGroupId||g.parentId||''));if(parent&&parent!==n)parent.children.push(n);}
    const roots=groups.filter(g=>!nodes.has(String(g.parentGroupId||g.parentId||''))).map(g=>nodes.get(String(g.id)));for(const entry of this.profileEntries)(nodes.get(String(entry.profile.group||''))||root).entries.push(entry);
    const count=(n,seen=new Set())=>{if(seen.has(n))return 0;seen.add(n);n.entries.sort((a,b)=>this.profileName(a).localeCompare(this.profileName(b)));n.totalProfiles=n.entries.length+n.children.reduce((total,c)=>total+count(c,seen),0);return n.totalProfiles;};roots.forEach(n=>count(n));if(root.entries.length)roots.push(root);this.profileGroups=roots.filter(n=>n.totalProfiles||n.entries.length);this.render();
  }
  async setProfileDirectory(entry) {
    const cfg=this.getConfig(),directory=String(entry.directory||'').trim(),id=String(entry.id),key=[entry.name,entry.host,entry.port,entry.user].map(x=>String(x??'').trim().toLowerCase()).join('|');
    const before={profileDirectories:cfg.profileDirectories,profileDirectoryKeys:cfg.profileDirectoryKeys,profiles:cfg.profiles};cfg.profileDirectories={...cfg.profileDirectories,[id]:directory};cfg.profileDirectoryKeys={...cfg.profileDirectoryKeys,[key]:directory};cfg.profiles={...cfg.profiles,[id]:{...(cfg.profiles?.[id]||{}),directory,name:entry.name,host:entry.host,port:entry.port,user:entry.user}};
    try{if(directory)fs.mkdirSync(directory,{recursive:true});await this.config.save();}catch(e){Object.assign(cfg,before);throw e;}if(!this.directoryStore.write(entry,directory))throw Error(this.t('保存日志路径失败。'));
  }
  async pickDefault() {const result=await this.electron.dialog.showOpenDialog(this.hostWindow?.getWindow?.(),{title:this.t('Choose log directory'),properties:['openDirectory','showHiddenFiles','createDirectory']});if(result?.filePaths?.length){const cfg=this.getConfig(),previous=cfg.defaultDirectory;cfg.defaultDirectory=result.filePaths[0];try{await this.config.save();}catch(e){cfg.defaultDirectory=previous;throw e;}this.render();}}
  async pickProfile(entry) {const result=await this.electron.dialog.showOpenDialog(this.hostWindow?.getWindow?.(),{title:this.t('Choose log directory'),properties:['openDirectory','showHiddenFiles','createDirectory']});if(result?.filePaths?.length){entry.directory=result.filePaths[0];await this.setProfileDirectory(entry);this.render();}}
  async toggleGroup(group) {const cfg=this.getConfig();cfg.collapsedGroups={...cfg.collapsedGroups,[group.key]:cfg.collapsedGroups?.[group.key]===false};await this.config.save();this.render();}
  async setAllGroupsCollapsed(collapsed) {const cfg=this.getConfig(),map={...cfg.collapsedGroups};for(const group of this.profileGroups){const pending=[group],seen=new Set();while(pending.length){const n=pending.pop();if(seen.has(n))continue;seen.add(n);map[n.key]=collapsed;pending.push(...n.children);}}cfg.collapsedGroups=map;void this.config.save();this.render();}
  formatSize(bytes) {const value=Number(bytes)||0;if(value<1024)return value+' B';const units=['KB','MB','GB'];let n=value/1024,i=0;while(n>=1024&&i<2){n/=1024;i++;}return n.toFixed(1)+' '+units[i];}
  loadLogsForEntry(entry) {
    const directory=entry.directory||this.getConfig().defaultDirectory;entry.logs=[];entry.logError='';if(!directory||!fs.existsSync(directory))return;const tag=profileLogTag(entry.id),name=filename(entry.name);
    try{for(const item of fs.readdirSync(directory,{withFileTypes:true})){if(!item.isFile()||!item.name.toLowerCase().endsWith('.log'))continue;const full=path.join(directory,item.name);let owner='',fd;try{fd=fs.openSync(full,'r');const buffer=Buffer.alloc(4096);const count=fs.readSync(fd,buffer,0,buffer.length,0);owner=buffer.subarray(0,count).toString('utf8').split(/\r?\n/).find(line=>line.startsWith('Profile ID : '))?.slice(13).trim()||'';}finally{if(fd!==undefined)fs.closeSync(fd);}let belongs=owner?owner===String(entry.id):item.name.includes('_'+tag+'_')||item.name.endsWith('_'+name+'.log')&&!/_p-[a-z0-9]+-[0-9a-f]{8}_/i.test(item.name);if(!belongs)continue;const stat=fs.statSync(full);entry.logs.push({name:item.name,path:full,size:stat.size,mtime:stat.mtime,modified:stat.mtime,date:stat.mtime});}entry.logs.sort((a,b)=>b.mtime-a.mtime);}catch(e){entry.logError=e.message;}
  }
  refreshLogs() {for(const e of this.profileEntries)this.loadLogsForEntry(e);this.render();}
  toggleLogs(entry) {entry.logsExpanded=!entry.logsExpanded;if(entry.logsExpanded)this.loadLogsForEntry(entry);this.render();}
  filteredLogs(entry) {const query=this.logSearch.toLowerCase(),rows=entry.logs.filter(log=>log.name.toLowerCase().includes(query)),sort=this.logSort;return rows.sort((a,b)=>sort==='oldest'?a.mtime-b.mtime:['largest','sizeDesc'].includes(sort)?b.size-a.size:sort==='sizeAsc'?a.size-b.size:['name','nameAsc'].includes(sort)?a.name.localeCompare(b.name):sort==='nameDesc'?b.name.localeCompare(a.name):b.mtime-a.mtime);}
  formatDateTime(value) {return new Date(value).toLocaleString();}
  async viewLog(log) {const message=await this.electron.shell.openPath(log.path);if(message)throw Error(message);}
  async openDirectory(entry) {const dir=typeof entry==='string'?entry:entry.directory||this.getConfig().defaultDirectory;if(fs.existsSync(dir)){const message=await this.electron.shell.openPath(dir);if(message)throw Error(message);}}
  render() {
    const host=this.mount||this.elementRef?.nativeElement;if(!host)return;host.replaceChildren();const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n;},button=(text,action)=>{const b=el('button','btn btn-secondary',this.t(text));b.type='button';b.addEventListener('click',async()=>{if(b.disabled)return;b.disabled=true;try{await action();}catch(e){const error=el('p','text-danger',this.t(e.message));host.prepend(error);}finally{b.disabled=false;}});return b;};
    const guard=fn=>(...args)=>Promise.resolve().then(()=>fn(...args)).catch(error=>host.prepend(el('p','text-danger',this.t(error.message))));const cfg=this.getConfig(),main=el('div','container-fluid p-3');main.append(el('h3',null,this.t('Session Log Manager')));const check=(label,key)=>{const box=el('label','d-flex align-items-center gap-2 mb-2'),input=el('input');input.type='checkbox';input.checked=cfg[key]!==false;if(key==='recordCommands')input.checked=cfg[key]===true;input.addEventListener('change',guard(async()=>{const old=cfg[key];cfg[key]=input.checked;try{await this.config.save();}catch(e){cfg[key]=old;input.checked=old;throw e;}}));box.append(input,el('span',null,this.t(label)));main.append(box);};check('Enable automatic logging','enabled');check('Record commands','recordCommands');main.append(el('small','text-warning',this.t('Input recording may include passwords and tokens.')));
    const pathBox=el('div','d-flex gap-2 mb-3'),pathInput=el('input','form-control');pathInput.value=cfg.defaultDirectory||'';pathInput.setAttribute('aria-label',this.t('Default log directory'));pathInput.addEventListener('change',guard(async()=>{const old=cfg.defaultDirectory;cfg.defaultDirectory=pathInput.value;try{await this.config.save();}catch(e){cfg.defaultDirectory=old;throw e;}}));pathBox.append(pathInput,button('Browse',()=>this.pickDefault()),button('Open Folder',()=>this.openDirectory(cfg.defaultDirectory)));main.append(pathBox);
    const filters=el('div','d-flex gap-2 mb-3'),search=el('input','form-control');search.type='search';search.value=this.logSearch;search.placeholder=this.t('Search logs');search.addEventListener('change',()=>{this.logSearch=search.value;this.render();});const sort=el('select','form-select');for(const [value,label]of [['newest','Newest first'],['oldest','Oldest first'],['sizeDesc','Largest first'],['sizeAsc','Smallest first'],['nameAsc','Name A-Z'],['nameDesc','Name Z-A']]){const option=el('option',null,this.t(label));option.value=value;sort.append(option);}sort.value=this.logSort;sort.addEventListener('change',()=>{this.logSort=sort.value;this.render();});filters.append(search,sort,button('Reload',()=>this.refreshProfiles()));main.append(filters,button('Expand all',()=>this.setAllGroupsCollapsed(false)),button('Collapse all',()=>this.setAllGroupsCollapsed(true)));
    const draw=(group,parent,depth,seen)=>{if(seen.has(group))return;seen.add(group);const box=el('div','mb-2');box.style.marginLeft=depth?'14px':'0';const expanded=cfg.collapsedGroups?.[group.key]===false;const toggle=button((expanded?'▾ ':'▸ ')+group.name+' ('+(group.totalProfiles||group.entries.length)+')',()=>this.toggleGroup(group));box.append(toggle);if(expanded){group.children.forEach(g=>draw(g,box,depth+1,seen));for(const entry of group.entries){const card=el('div','card p-2 my-2'),row=el('div','d-flex align-items-center gap-2');row.style.flexWrap='wrap';row.append(el('strong',null,this.profileName(entry)));const input=el('input','form-control');input.value=entry.directory;input.placeholder=cfg.defaultDirectory;input.addEventListener('change',guard(async()=>{const previous=entry.directory;entry.directory=input.value;try{await this.setProfileDirectory(entry);}catch(error){entry.directory=previous;input.value=previous;throw error;}}));row.append(input,button('Browse',()=>this.pickProfile(entry)),button('Open Folder',()=>this.openDirectory(entry)),button('Logs',()=>this.toggleLogs(entry)));card.append(row);if(entry.logsExpanded){for(const log of this.filteredLogs(entry)){const line=el('div','d-flex align-items-center gap-2 py-1');line.append(el('span',null,log.name+' · '+this.formatDateTime(log.mtime)+' · '+this.formatSize(log.size)),button('View',()=>this.viewLog(log)));card.append(line);}if(entry.logError)card.append(el('p','text-danger',entry.logError));}box.append(card);}}parent.append(box);};for(const group of this.profileGroups)draw(group,main,0,new Set());host.append(main);
  }
}
module.exports={AutoLoggerSettingsTabComponent};
